from pathlib import Path
import sys
root=Path(sys.argv[1]) if len(sys.argv)>1 else Path("/opt/olamide/repo")
patches={'adminWorkspaceUi.js': [("active='providers'", "active='overview',monitoring=null"), ('  if(!layout||!isSuper())return;collect();', '  if(!layout||!isSuper())return false;collect();'), ("Check the deployment result.';return;", "Check the deployment result.';return false;"), ("  else groups.get('providers')?.section.scrollIntoView?.({behavior:'smooth',block:'start'});", "  else groups.get('providers')?.section.scrollIntoView?.({behavior:'smooth',block:'start'});\n  return true;"), ('main.append(overview);for(const [key,name]of categories)', 'main.append(overview);monitoring=setupAdminMonitoringUi({host:overview,document,isSuper,getUserId,navigate:openTool,visible:()=>!overview.hidden});for(const [key,name]of categories)'), ('function stop(){observer?.disconnect();', 'function stop(){monitoring?.dispose();monitoring=null;observer?.disconnect();'), ("const overviewButton=el('button','Overview');", "const overviewButton=el('button','Monitoring dashboard');"), ("active='overview';search.value='';filter();};nav.append(overviewButton)", "active='overview';search.value='';filter();void monitoring.refresh();};nav.append(overviewButton)")], 'groups.js': [('  return { refresh };', "  document.addEventListener('admin-monitor-select',async event=>{if(event.detail?.kind!=='users')return;try{await refresh();const id=event.detail.id;if(users.some(u=>u.id===id)){root.querySelector('#group-user').value=id;fillUser();root.querySelector('#group-user').focus();}}catch(error){status(error.message);}});\n  return { refresh };")], 'fleetNetworkAdmin.js': [('  return {refresh:()=>refresh().catch(e=>status.textContent=e.message)};', "  document.addEventListener('admin-monitor-select',async event=>{if(event.detail?.kind!=='equipment')return;try{await refresh();const device=devices.find(d=>d.id===event.detail.id);if(device){setForm(device);form.scrollIntoView?.({block:'center'});form.elements.name.focus();}}catch(error){status.textContent=error.message;}});\n  return {refresh:()=>refresh().catch(e=>status.textContent=e.message)};")], 'serverFleetAdmin.js': [('  return {refresh:()=>Promise.all([refresh(),report()]).catch(e=>status.textContent=e.message)};', "  document.addEventListener('admin-monitor-select',async event=>{if(event.detail?.kind!=='servers')return;try{await refresh();const row=[...$('fleet-nodes').children].find(li=>li.dataset.id===event.detail.id);row?.scrollIntoView?.({block:'center'});row?.querySelector('input,button')?.focus();}catch(error){status.textContent=error.message;}});\n  return {refresh:()=>Promise.all([refresh(),report()]).catch(e=>status.textContent=e.message)};")], 'operationsAdmin.js': [('  return {refresh:()=>refresh().catch(e=>status.textContent=e.message)};', "  document.addEventListener('admin-monitor-select',event=>{if(event.detail?.kind!=='discovery')return;const t=event.detail.record,form=$('redirector-form');if(!t||!form)return;for(const [field,key] of [['name','name'],['region','region'],['nodeId','node_id'],['wssUrl','wss_url'],['weight','weight']])form.elements[field].value=t[key]??'';form.elements.enabled.checked=!!t.enabled;form.elements.targetId.value=t.id;form.elements.name.focus();});\n  return {refresh:()=>refresh().catch(e=>status.textContent=e.message)};")]}
changes=[]
for name,replacements in patches.items():
 p=root/"apps/web/src"/name
 if not p.exists():raise SystemExit("Required monitoring settings module missing: "+name)
 s=p.read_text()
 if "// ADMIN_MONITORING_DASHBOARD_V1" in s:continue
 for a,b in replacements:
  if s.count(a)!=1:raise SystemExit("Unknown monitoring integration anchor; no sources changed: "+name+": "+a)
  s=s.replace(a,b)
 s=("import {setupAdminMonitoringUi} from './adminMonitoringUi.js';\n" if name=="adminWorkspaceUi.js" else "")+"// ADMIN_MONITORING_DASHBOARD_V1\n"+s
 changes.append((p,s))
for p,s in changes:p.write_text(s)
print("Monitoring dashboard and record selection hooks installed.")
